def transform(grid):
    h, w = len(grid), len(grid[0])
    # The one-cell solid divider separates two congruent panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            top, bottom = grid[:r], grid[r + 1:]
            shared = {v for row in top for v in row} & {v for row in bottom for v in row}
            bg = next(iter(shared))
            return [[3 if a == b else bg for a, b in zip(ra, rb)] for ra, rb in zip(top, bottom)]
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)) and c == w - c - 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            shared = {v for row in left for v in row} & {v for row in right for v in row}
            bg = next(iter(shared))
            return [[3 if a == b else bg for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
    raise ValueError('No centered solid divider with equal panels found')
